#include <stdio.h>

int match(char *r, char *t) {
    if (r[0] == '\0') return t[0] == '\0';
    if (r[1] == '*') {
        int m = match(r+2, t);
        if (t[0] != '\0' && (r[0] == '.' || r[0] == t[0]))
            m = m || match(r, t+1);
        return m;
    }
    if (t[0] != '\0' && (r[0] == '.' || r[0] == t[0]))
        return match(r+1, t+1);
    return 0;
}

int main() {
    printf("%d\n", match("a*b", "b"));
    printf("%d\n", match("a.b", "axb"));
    printf("%d\n", match("ab*c", "abc"));
    return 0;
}
